cd /home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill && python3 - <<'EOF'
import subprocess
branches=['rachel','monica','phoebe','joey','chandler','ross']
cnt=0
shas=set()
for b in branches:
    out=subprocess.check_output(['git','rev-list','--reverse',f'origin/friend/{b}'],text=True).split()
    for sha in out:
        msg=subprocess.check_output(['git','show',sha,'-s','--format=%B'],text=True)
        if 'Friend-Message: 1' in msg:
            # parse episode
            ep=None
            for line in msg.splitlines():
                if line.startswith('Episode:'):
                    ep=line.split(':',1)[1].strip()
            if ep=='S03/E23':
                cnt+=1
                shas.add(sha)
print('S03/E23 friend-message commits:',cnt)
EOF
